const CACHE_NAME="legestue-cache-v2",OFFLINE_FALLBACK="index.html";self.addEventListener("install",e=>{console.log("[Service Worker] Installerer..."),e.waitUntil(caches.open(CACHE_NAME).then(e=>(console.log("[Service Worker] Cacher offline-side"),e.add(OFFLINE_FALLBACK)))),self.skipWaiting()}),self.addEventListener("activate",e=>{console.log("[Service Worker] Aktiverer..."),e.waitUntil(caches.keys().then(e=>Promise.all(e.map(e=>{if(e!==CACHE_NAME)return console.log("[Service Worker] Fjerner gammel cache:",e),caches.delete(e)})))),self.clients.claim()}),self.addEventListener("fetch",e=>{const{request:t}=e;if(t.method!=="GET"||!t.url.startsWith("http"))return;e.respondWith(fetch(t).then(async e=>{if(e.status===200&&e.type==="basic"){const n=await caches.open(CACHE_NAME);n.put(t,e.clone())}return e}).catch(async()=>{console.log("[Service Worker] Netværk fejlede, søger i cachen for:",t.url);const e=await caches.match(t);if(e)return e;if(t.mode==="navigate")return caches.match(OFFLINE_FALLBACK)}))})